import{_t as e,it as t,n,rt as r}from"./chunks/framework.kOqVNnGI.js";var i=JSON.parse(`{"title":"Supply-Chain Security Posture","description":"","frontmatter":{},"headers":[],"relativePath":"supply-chain.md","filePath":"supply-chain.md","lastUpdated":1792335976000}`),a={name:`supply-chain.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="supply-chain-security-posture" tabindex="-1">Supply-Chain Security Posture <a class="header-anchor" href="#supply-chain-security-posture" aria-label="Permalink to “Supply-Chain Security Posture”">​</a></h1><p>This document maps every supply-chain and security control in the Glaucus repository to the mechanism that implements it and where it runs.</p><h2 id="control-matrix" tabindex="-1">Control Matrix <a class="header-anchor" href="#control-matrix" aria-label="Permalink to “Control Matrix”">​</a></h2><table tabindex="0"><thead><tr><th>Control</th><th>Mechanism</th><th>Local mise task</th><th>Where it runs in CI</th></tr></thead><tbody><tr><td><strong>Memory safety</strong></td><td><code>#![forbid(unsafe_code)]</code> on glaucus-core / glaucus-ast / glaucus-cst</td><td>— (compiler-enforced)</td><td>every build</td></tr><tr><td><strong>Undefined behaviour</strong></td><td>Miri with <code>-Zmiri-strict-provenance</code></td><td><em>no task defined</em></td><td><strong>not wired</strong> — see below</td></tr><tr><td><strong>Dependency advisories</strong></td><td><code>cargo audit</code> against the RustSec advisory database</td><td><code>mise run cargo:audit</code></td><td><code>cicd.yml</code> — <code>lint</code> job, via the hk <code>audit</code> step</td></tr><tr><td><strong>License &amp; ban policy</strong></td><td><code>cargo deny check</code> (license allowlist, multiple-versions ban, unknown-registries ban)</td><td><code>mise run cargo:deny</code></td><td><code>cicd.yml</code> — <code>lint</code> job, via the hk <code>deny</code> step</td></tr><tr><td><strong>Secret scanning</strong></td><td><code>gitleaks</code></td><td><code>hk run gitleaks</code></td><td><code>cicd.yml</code> — <code>lint</code> job, via the hk <code>gitleaks</code> step</td></tr><tr><td><strong>Supply-chain audits</strong></td><td><code>cargo vet</code> — records in <code>supply-chain/audits.toml</code></td><td><code>mise run cargo:vet</code></td><td><strong>not wired</strong> — see below</td></tr><tr><td><strong>License compliance</strong></td><td>REUSE 3.3 — every file covered via <code>REUSE.toml</code> globs + <code>LICENSES/</code></td><td><code>mise run comply</code></td><td><code>cicd.yml</code> — <code>lint</code> job, via the hk <code>comply</code> step</td></tr><tr><td><strong>Static analysis</strong></td><td>CodeQL</td><td>CI only</td><td><code>cicd.yml</code> — <code>sast</code> job → <code>codeql.yml</code></td></tr><tr><td><strong>Build provenance</strong></td><td>SLSA Build Level 3 via <code>actions/attest</code>, run inside the reusable <code>package.yml</code></td><td>CI only</td><td><code>publish.yml</code> → <code>package.yml</code></td></tr><tr><td><strong>Artifact signing</strong></td><td>sigstore/cosign keyless signing (<code>.cosign.bundle</code> per artifact)</td><td>CI only</td><td><code>publish.yml</code></td></tr><tr><td><strong>Container images</strong></td><td>One OCI index over <code>linux/amd64</code> + <code>linux/arm64</code>, each built natively on its own runner; build provenance via <code>actions/attest</code>, pushed to ghcr.io (<code>gh attestation verify oci://ghcr.io/elioseverojunior/glaucus:&lt;tag&gt; --repo elioseverojunior/glaucus</code>)</td><td><code>mise run docker:build</code></td><td><code>docker-release.yml</code></td></tr><tr><td><strong>Project scorecard</strong></td><td>OpenSSF Scorecard (<code>ossf/scorecard-action</code>); weekly schedule</td><td>CI only</td><td><code>scorecards.yml</code></td></tr><tr><td><strong>Fuzzing</strong></td><td>9 <code>cargo-fuzz</code> targets — <code>fuzz_scanner</code>, <code>fuzz_parser</code>, <code>fuzz_round_trip</code>, <code>fuzz_limits</code>, <code>fuzz_alias_graph</code>, <code>fuzz_serde</code>, <code>fuzz_cst_roundtrip</code>, <code>fuzz_lossless_edit</code>, <code>fuzz_merge_keys</code></td><td><code>mise run fuzz:all</code></td><td><code>nightly.yml</code> — <code>fuzz</code> job</td></tr><tr><td><strong>Test coverage</strong></td><td><code>cargo-tarpaulin</code>, LLVM engine, <strong>code and doctests both at 100%</strong> (see below)</td><td><code>mise run coverage</code></td><td><code>cicd.yml</code> — <code>tests</code> job</td></tr><tr><td><strong>Spec conformance</strong></td><td>Official YAML test suite, 402/402, enforced at a 100% floor</td><td><code>mise run test</code></td><td><code>cicd.yml</code> — <code>tests</code> job</td></tr></tbody></table><h3 id="coverage-one-invocation-code-and-doctests-alike" tabindex="-1">Coverage: one invocation, code and doctests alike <a class="header-anchor" href="#coverage-one-invocation-code-and-doctests-alike" aria-label="Permalink to “Coverage: one invocation, code and doctests alike”">​</a></h3><p>The gate is a single tarpaulin run, and it covers <strong>both</strong> unit/integration tests and doctests against the same 100% floor — a doctest is documentation that executes, so it is held to the same standard as the code it documents:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tarpaulin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --engine</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llvm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --features</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> glaucus/cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --run-types</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Tests</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --run-types</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Doctests</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --fail-under</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span></span></code></pre></div><div><p>The threshold is declared once, in <code>mise.toml</code> as <code>RUST_COVERAGE_THRESHOLD = &quot;100&quot;</code>, and every other consumer reads it rather than restating it: the <code>coverage</code> task defaults <code>--threshold</code> to it, and <code>cicd.yml</code> passes <code>\${{ vars.RUST_COVERAGE_THRESHOLD || &#39;100&#39; }}</code>. <code>codecov.yml</code> sets <code>target: 100%</code> with <code>threshold: 0%</code> on project, patch and every component, so no regression is tolerated there either.</p></div><h3 id="controls-that-are-not-wired-into-ci" tabindex="-1">Controls that are NOT wired into CI <a class="header-anchor" href="#controls-that-are-not-wired-into-ci" aria-label="Permalink to “Controls that are NOT wired into CI”">​</a></h3><p>Recorded explicitly rather than left to be inferred from the table, because a security document that overstates its own posture is worse than one that admits a gap:</p><ul><li><strong>Miri</strong> — no <code>miri</code> task exists in <code>mise.toml</code> and <code>nightly.yml</code> defines only a <code>fuzz</code> job. The Miri configuration survives as a comment in that workflow.</li><li><strong><code>cargo vet</code></strong> — the <code>cargo:vet</code> task exists and is deliberately non-blocking (<code>|| true</code>) until the dependency tree is certified, but nothing invokes it in CI.</li></ul><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to “Notes”">​</a></h2><p><strong>Ordering in the lint job</strong> — <code>cargo audit</code> intentionally runs before <code>cargo deny</code>. <code>cargo audit</code> clones the RustSec advisory database into <code>~/.cargo/advisory-db</code>; <code>cargo deny</code>&#39;s <code>advisories</code> check reuses that directory and will fail if it is non-empty when the clone is attempted.</p><p><strong>cargo vet is non-blocking</strong> — the <code>cargo:vet</code> task carries <code>continue-on-error: true</code> until the dependency audit set is fully populated with <code>cargo vet certify</code> entries. Remove that flag once the tree is audited.</p><p><strong>REUSE compliance</strong> — <code>REUSE.toml</code> uses glob patterns to cover every file class (Rust sources carry SPDX headers inline; config files, docs, and CI workflows are covered by catch-all globs). Run <code>reuse lint</code> or <code>mise run comply</code> to verify compliance locally.</p><p><strong>SLSA / cosign are release-only</strong> — these controls run on tag pushes (<code>on: push: tags: [&#39;v*&#39;]</code>) and are not part of the PR gate. They operate on the published <code>.tar.gz</code> / <code>.sha256</code> release assets.</p><p><strong>Verifying provenance</strong> — the attestation is signed by the reusable <code>package.yml</code>, not by its caller, which is what makes it Build Level 3. Pin that signer when verifying a downloaded crate:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> attestation</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> glaucus-</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">versio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.crate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --repo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> elioseverojunior/glaucus</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --signer-workflow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> elioseverojunior/glaucus/.github/workflows/package.yml</span></span></code></pre></div><p>Each Release also carries the bundle as <code>provenance.sigstore.json</code>, for offline verification with <code>--bundle provenance.sigstore.json</code>.</p><p><strong>Miri scope</strong> — Miri tests <code>glaucus-core</code> and <code>glaucus-ast</code>. <code>glaucus-serde</code> and <code>glaucus-cst</code> pull in <code>serde</code> proc-macros which Miri does not yet fully support; they are intentionally excluded.</p>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};